content.css:
[data-section-id='home-premium-intro'] .ice-hero-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; padding: 2rem; background: var(--cms-backgrounds-frost); border-radius: var(--cms-border-radius-card); box-shadow: var(--cms-shadows-card); }
[data-section-id='home-premium-intro'] .cms-eyebrow { color: var(--cms-colors-primary); font-weight: 700; }
[data-section-id='home-premium-intro'] .ice-check-list { display: grid; gap: 0.5rem; padding-left: 1rem; }
[data-section-id='home-premium-intro'] .ice-cta-link { color: var(--cms-colors-primary); font-weight: 700; text-decoration: underline; }

[data-section-id='home-event-fit'] .ice-event-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1rem; }
[data-section-id='home-event-fit'] .ice-event-card { padding: 1.25rem; background: var(--cms-colors-surface); border: 1px solid var(--cms-colors-border); border-radius: var(--cms-border-radius-card); }
[data-section-id='home-event-fit'] .ice-event-card h3 { color: var(--cms-colors-ink); }

[data-section-id='home-planning-comparison'] .ice-planning-table { width: 100%; border: 1px solid var(--cms-colors-border); border-radius: var(--cms-border-radius-card); background: var(--cms-colors-surface); }
[data-section-id='home-planning-comparison'] .ice-planning-table th { text-align: left; color: var(--cms-colors-primary); }
[data-section-id='home-planning-comparison'] .ice-planning-table th, [data-section-id='home-planning-comparison'] .ice-planning-table td { padding: 1rem; }
